const PUBLIC_AGENT_NAME_PATTERN=/^[a-z0-9](?:[a-z0-9_-]*[a-z0-9])?$/;function isValidPublicAgentName(e){return PUBLIC_AGENT_NAME_PATTERN.test(e)}function assertValidPublicAgentName(e,t){if(!isValidPublicAgentName(e))throw Error(`${t} ${JSON.stringify(e)} is invalid. Use lowercase letters, numbers, hyphens, or underscores, beginning and ending with a letter or number.`)}export{assertValidPublicAgentName};